-- Durable account mail. Only trusted source ledgers and owner-issued gifts create rewards.
create table private.reward_inbox_v1(
 id uuid primary key default gen_random_uuid(), account_id uuid not null references auth.users(id) on delete cascade,
 source_key text not null, source_kind text not null check(source_kind in ('party','guild','dungeon','gift')),
 source_id uuid not null, title text not null, body text not null default '', attachments jsonb not null default '[]',
 created_at timestamptz not null default now(), claimed_at timestamptz,
 unique(account_id,source_key)
);
create index reward_inbox_account_v1 on private.reward_inbox_v1(account_id,claimed_at,created_at desc,id);
create table private.reward_gift_catalog_v1(id text primary key,kind text not null check(kind in ('gold','item','candy')),resource_id text not null,name text not null,max_quantity integer not null);
create table private.reward_gift_campaigns_v1(
 id uuid primary key default gen_random_uuid(), actor_id uuid not null references auth.users(id),request_id uuid not null,
 title text not null,body text not null,reason text not null,audience text not null check(audience in ('all','account')),
 target_account_id uuid,attachments jsonb not null,created_at timestamptz not null default now(),sent_at timestamptz,
 unique(actor_id,request_id)
);
create table private.reward_gift_recipients_v1(campaign_id uuid not null references private.reward_gift_campaigns_v1(id) on delete cascade,account_id uuid not null references auth.users(id) on delete cascade,primary key(campaign_id,account_id));
alter table private.reward_inbox_v1 enable row level security;
alter table private.reward_gift_catalog_v1 enable row level security;
alter table private.reward_gift_campaigns_v1 enable row level security;
alter table private.reward_gift_recipients_v1 enable row level security;
revoke all on private.reward_inbox_v1,private.reward_gift_catalog_v1,private.reward_gift_campaigns_v1,private.reward_gift_recipients_v1 from public,anon,authenticated;
grant all on private.reward_inbox_v1,private.reward_gift_catalog_v1,private.reward_gift_campaigns_v1,private.reward_gift_recipients_v1 to service_role;

create function private.reward_inbox_sync_v1(uid uuid) returns void language plpgsql security definer set search_path='' as $$
begin
 insert into private.reward_inbox_v1(account_id,source_key,source_kind,source_id,title,body,attachments,created_at,claimed_at)
 select uid,'party:'||i.definition_id||':'||i.season_key||':'||r.reward_key,'party',r.id,
  case when r.reward_key like 'tier:%' then initcap(substr(r.reward_key,6))||' party reward' else 'Party contract reward' end,
  'Earned together. Your reward remains available after the weekly reset.',jsonb_build_array(jsonb_build_object('kind','gold','resourceId','gold','name','Gold','quantity',coalesce((r.reward_json->>'gold')::integer,0))),r.created_at,
  coalesce(r.claimed_at,(select created_at from public.server_action_receipts a where a.account_id=uid and a.action='party_contract_reward' and a.idempotency_key=i.definition_id||':'||i.season_key||':'||r.reward_key limit 1))
 from public.party_contract_reward_entitlements_v16 r join public.party_contract_instances_v16 i on i.id=r.instance_id where r.account_id=uid
 on conflict(account_id,source_key) do update set claimed_at=excluded.claimed_at where private.reward_inbox_v1.claimed_at is null and excluded.claimed_at is not null;
 insert into private.reward_inbox_v1(account_id,source_key,source_kind,source_id,title,body,attachments,claimed_at)
 select uid,'guild:'||p.id,'guild',p.id,'Guild weekly reward','Your personal contribution qualified for this completed guild project.',
  '[{"kind":"gold","resourceId":"gold","name":"Gold","quantity":500}]',r.claimed_at
 from public.guild_project_instances p join public.guild_project_member_progress m on m.project_instance_id=p.id and m.account_id=uid
 left join public.guild_project_reward_claims r on r.project_instance_id=p.id and r.account_id=uid and r.reward_key='completion'
 where p.template_id='guild_weekly_shared_effort' and p.status='completed' and m.raw_points>=p.personal_reward_threshold
 on conflict(account_id,source_key) do update set claimed_at=excluded.claimed_at where private.reward_inbox_v1.claimed_at is null and excluded.claimed_at is not null;
 insert into private.reward_inbox_v1(account_id,source_key,source_kind,source_id,title,body,attachments,created_at,claimed_at)
 select uid,'dungeon:'||e.id,'dungeon',e.id,'Dungeon reward','Reward charges and bonuses are calculated when claimed.',
  jsonb_build_array(jsonb_build_object('kind','marks','resourceId','expedition_marks','name','Expedition Marks','quantity',coalesce((e.reward_json->>'marks')::integer,(e.reward_json->>'enhanced_marks')::integer,0))),e.period_date_key::timestamptz,e.claimed_at
 from public.coop_reward_entitlements e where e.recipient_account_id=uid
 on conflict(account_id,source_key) do update set claimed_at=excluded.claimed_at where private.reward_inbox_v1.claimed_at is null and excluded.claimed_at is not null;
end $$;

create function public.reward_inbox_state_v1(p_history boolean default false,p_offset integer default 0) returns jsonb
language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();rows jsonb;total integer;pending integer;
begin
 if uid is null then raise exception 'AUTH_REQUIRED';end if;
 perform private.reward_inbox_sync_v1(uid);
 select count(*) into pending from private.reward_inbox_v1 where account_id=uid and claimed_at is null;
 select count(*) into total from private.reward_inbox_v1 where account_id=uid and (claimed_at is not null)=p_history;
 select coalesce(jsonb_agg(to_jsonb(t) order by t."createdAt" desc,t.id),'[]') into rows from (
  select id,source_kind as source,title,body,attachments,created_at as "createdAt",claimed_at as "claimedAt" from private.reward_inbox_v1
  where account_id=uid and (claimed_at is not null)=p_history order by created_at desc,id limit 40 offset greatest(0,coalesce(p_offset,0))) t;
 return jsonb_build_object('entries',rows,'pendingCount',pending,'total',total);
end $$;

create function public.reward_inbox_claim_v1(p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();mail private.reward_inbox_v1;g public.online_game_states;a jsonb;s jsonb;result jsonb;added integer;amount bigint;gift_gold bigint:=0;stacks jsonb;
begin
 if uid is null then raise exception 'AUTH_REQUIRED';end if;
 -- Match gameplay lock order; party's original claim path uses the reward lock first.
 perform pg_advisory_xact_lock(hashtextextended('party-reward:'||uid,0));
 perform pg_advisory_xact_lock(hashtextextended('party-account:'||uid,0));
 select * into g from public.online_game_states where account_id=uid for update;
 if g.character_id is null then raise exception 'Sync a character before claiming rewards.';end if;
 select * into mail from private.reward_inbox_v1 where id=p_id and account_id=uid for update;
 if not found then raise exception 'REWARD_NOT_FOUND';end if;
 if mail.claimed_at is not null then return '{"alreadyClaimed":true}';end if;
 s:=g.state;
 if mail.source_kind='party' then
  begin result:=public.claim_party_contract_reward_v16(mail.source_id,g.character_id);
  exception when raise_exception then if sqlerrm<>'contract_scope_reward_already_claimed' then raise;end if;result:='{"alreadyClaimed":true}';end;
 elsif mail.source_kind='dungeon' then
  result:=public.claim_coop_reward(mail.source_id,'inbox:'||mail.id);
 elsif mail.source_kind='guild' then
  insert into public.guild_project_reward_claims(project_instance_id,account_id,reward_key) values(mail.source_id,uid,'completion') on conflict do nothing;
  get diagnostics added=row_count;
  if added>0 then insert into public.character_wallets(character_id,gold) values(g.character_id,500) on conflict(character_id) do update set gold=public.character_wallets.gold+excluded.gold,updated_at=now();end if;
  result:=jsonb_build_object('alreadyClaimed',added=0,'gold',case when added>0 then 500 else 0 end);
 else
  for a in select * from jsonb_array_elements(mail.attachments) loop
   amount:=(a->>'quantity')::bigint;
   if a->>'kind'='gold' then
    gift_gold:=gift_gold+amount;
   elsif a->>'kind'='candy' then
    s:=jsonb_set(s,'{account,eventCandyChargesById}',coalesce(s#>'{account,eventCandyChargesById}','{}')||jsonb_build_object(a->>'resourceId',coalesce((s#>>array['account','eventCandyChargesById',a->>'resourceId'])::bigint,0)+amount),true);
   elsif a->>'kind'='item' then
    stacks:=coalesce(s#>'{inventory,stacks}','[]');
    if not exists(select 1 from jsonb_array_elements(stacks) e where e->>'itemId'=a->>'resourceId') and jsonb_array_length(stacks)+jsonb_array_length(coalesce(s#>'{inventory,gear}','[]'))>=coalesce((s#>>'{inventory,capacity}')::integer,0) then
     return jsonb_build_object('blocked',true,'message','Make room in your inventory. This reward stays in your inbox.');
    end if;
    s:=public.veldryn_game_state_add_stackable_v1(s,a->>'resourceId',amount::integer,floor(extract(epoch from now())*1000)::bigint);
   else raise exception 'UNSUPPORTED_REWARD';end if;
  end loop;
  if gift_gold>0 then insert into public.character_wallets(character_id,gold) values(g.character_id,gift_gold) on conflict(character_id) do update set gold=public.character_wallets.gold+excluded.gold,updated_at=now();end if;
  result:='{"alreadyClaimed":false}';
 end if;
 s:=jsonb_set(s,'{character,gold}',to_jsonb(coalesce((select gold from public.character_wallets where character_id=g.character_id),0)),true);
 update public.online_game_states set state=s,revision=revision+1,updated_at=now() where account_id=uid;
 update private.reward_inbox_v1 set claimed_at=now() where id=mail.id;
 return result;
end $$;

-- Claims run individually so a full inventory does not block other messages.
create function public.reward_inbox_claim_all_v1() returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();r record;result jsonb;n integer:=0;blocked integer:=0;
begin
 if uid is null then raise exception 'AUTH_REQUIRED';end if;
 perform private.reward_inbox_sync_v1(uid);
 for r in select id from private.reward_inbox_v1 where account_id=uid and claimed_at is null order by created_at,id loop
  result:=public.reward_inbox_claim_v1(r.id);
  if coalesce((result->>'blocked')::boolean,false) then blocked:=blocked+1;else n:=n+1;end if;
 end loop;
 return jsonb_build_object('claimed',n,'blocked',blocked);
end $$;

create function public.reward_gift_admin_v1(p_actor uuid,p_action text,p_payload jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare campaign private.reward_gift_campaigns_v1;c private.reward_gift_catalog_v1;v_audience text;recipient uuid;qty integer;counted integer;rid uuid;existing private.reward_gift_campaigns_v1;
begin
 if not exists(select 1 from public.liveops_admin_users where account_id=p_actor and role='owner' and enabled) then raise exception 'insufficient_admin_role';end if;
 if p_action='state' then return jsonb_build_object('catalog',(select coalesce(jsonb_agg(to_jsonb(c) order by c.kind,c.name),'[]') from private.reward_gift_catalog_v1 c),
  'campaigns',(select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc),'[]') from (select c.*,(select count(*) from private.reward_gift_recipients_v1 r where r.campaign_id=c.id) as recipient_count from private.reward_gift_campaigns_v1 c order by created_at desc limit 50)t));end if;
 if p_action='preview' then
  rid:=(p_payload->>'requestId')::uuid;v_audience:=p_payload->>'audience';recipient:=nullif(p_payload->>'accountId','')::uuid;qty:=(p_payload->>'quantity')::integer;
  if rid is null or coalesce(v_audience,'') not in ('all','account') then raise exception 'invalid_gift_request';end if;
  select * into c from private.reward_gift_catalog_v1 where id=p_payload->>'catalogId';
  if not found or qty is null or qty<1 or qty>c.max_quantity then raise exception 'invalid_gift_reward';end if;
  if char_length(trim(coalesce(p_payload->>'title',''))) not between 3 and 100 or char_length(coalesce(p_payload->>'body',''))>1000 or char_length(trim(coalesce(p_payload->>'reason',''))) not between 10 and 1000 then raise exception 'invalid_gift_message_or_reason';end if;
  if v_audience='account' and (recipient is null or not exists(select 1 from auth.users where id=recipient)) then raise exception 'recipient_not_found';end if;
  perform pg_advisory_xact_lock(hashtextextended('gift:'||p_actor||':'||rid,0));
  select * into existing from private.reward_gift_campaigns_v1 where actor_id=p_actor and request_id=rid;
  if found then
   if existing.title<>trim(p_payload->>'title') or existing.body<>coalesce(p_payload->>'body','') or existing.audience<>v_audience or existing.target_account_id is distinct from recipient or existing.attachments<>jsonb_build_array(jsonb_build_object('kind',c.kind,'resourceId',c.resource_id,'name',c.name,'quantity',qty)) then raise exception 'gift_request_conflict';end if;
   campaign:=existing;
  else
   insert into private.reward_gift_campaigns_v1(actor_id,request_id,title,body,reason,audience,target_account_id,attachments)
   values(p_actor,rid,trim(p_payload->>'title'),coalesce(p_payload->>'body',''),trim(p_payload->>'reason'),v_audience,recipient,jsonb_build_array(jsonb_build_object('kind',c.kind,'resourceId',c.resource_id,'name',c.name,'quantity',qty))) returning * into campaign;
   insert into private.reward_gift_recipients_v1(campaign_id,account_id) select campaign.id,id from auth.users where deleted_at is null and (v_audience='all' or id=recipient);
  end if;
 elsif p_action='send' then
  select * into campaign from private.reward_gift_campaigns_v1 where id=(p_payload->>'id')::uuid and actor_id=p_actor for update;
  if not found then raise exception 'gift_not_found';end if;
  if p_payload->>'confirmation' is distinct from 'SEND GIFT' then raise exception 'confirmation_required';end if;
  if campaign.sent_at is null then
   insert into private.reward_inbox_v1(account_id,source_key,source_kind,source_id,title,body,attachments)
    select account_id,'gift:'||campaign.id,'gift',campaign.id,campaign.title,campaign.body,campaign.attachments from private.reward_gift_recipients_v1 where campaign_id=campaign.id on conflict do nothing;
   update private.reward_gift_campaigns_v1 set sent_at=now() where id=campaign.id returning * into campaign;
   insert into public.liveops_admin_audit_log(actor_account_id,actor_role,action,target_type,target_id,detail_json)
    values(p_actor,'owner','sendRewardGift','reward_gift',campaign.id::text,jsonb_build_object('reason',campaign.reason,'audience',campaign.audience,'attachments',campaign.attachments,'recipients',(select count(*) from private.reward_gift_recipients_v1 where campaign_id=campaign.id)));
  end if;
 else raise exception 'invalid_gift_action';end if;
 select count(*) into counted from private.reward_gift_recipients_v1 where campaign_id=campaign.id;
 return to_jsonb(campaign)||jsonb_build_object('recipient_count',counted);
end $$;

revoke all on function private.reward_inbox_sync_v1(uuid),public.reward_inbox_state_v1(boolean,integer),public.reward_inbox_claim_v1(uuid),public.reward_inbox_claim_all_v1(),public.reward_gift_admin_v1(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.reward_inbox_state_v1(boolean,integer),public.reward_inbox_claim_v1(uuid),public.reward_inbox_claim_all_v1() to authenticated;
grant execute on function private.reward_inbox_sync_v1(uuid),public.reward_gift_admin_v1(uuid,text,jsonb) to service_role;
insert into private.reward_gift_catalog_v1 select * from jsonb_to_recordset($catalog$[{"id":"gold","kind":"gold","resource_id":"gold","name":"Gold","max_quantity":100000},{"id":"HOLY_WATER","kind":"item","resource_id":"HOLY_WATER","name":"Holy Water","max_quantity":1000},{"id":"DEWLEAF","kind":"item","resource_id":"DEWLEAF","name":"Dewleaf","max_quantity":1000},{"id":"RIVER_MINT","kind":"item","resource_id":"RIVER_MINT","name":"River Mint","max_quantity":1000},{"id":"IRONBLOOM","kind":"item","resource_id":"IRONBLOOM","name":"Ironbloom","max_quantity":1000},{"id":"CAVELICHEN","kind":"item","resource_id":"CAVELICHEN","name":"Cavelichen","max_quantity":1000},{"id":"CROWN_SAGE","kind":"item","resource_id":"CROWN_SAGE","name":"Crown Sage","max_quantity":1000},{"id":"OATHBLOSSOM","kind":"item","resource_id":"OATHBLOSSOM","name":"Oathblossom","max_quantity":1000},{"id":"SUNSCALE","kind":"item","resource_id":"SUNSCALE","name":"Sunscale Bloom","max_quantity":1000},{"id":"FROSTBLOOM","kind":"item","resource_id":"FROSTBLOOM","name":"Frostbell Flower","max_quantity":1000},{"id":"ASHEN_MYRRH","kind":"item","resource_id":"ASHEN_MYRRH","name":"Ashen Myrrh","max_quantity":1000},{"id":"ASTERFALL_BOTANICAL_ESSENCE","kind":"item","resource_id":"ASTERFALL_BOTANICAL_ESSENCE","name":"Asterfall Botanical Essence","max_quantity":1000},{"id":"SUNSCAR_BOTANICAL_ESSENCE","kind":"item","resource_id":"SUNSCAR_BOTANICAL_ESSENCE","name":"Sunscar Botanical Essence","max_quantity":1000},{"id":"FROSTMARCH_BOTANICAL_ESSENCE","kind":"item","resource_id":"FROSTMARCH_BOTANICAL_ESSENCE","name":"Frostmarch Botanical Essence","max_quantity":1000},{"id":"ASHLANDS_BOTANICAL_ESSENCE","kind":"item","resource_id":"ASHLANDS_BOTANICAL_ESSENCE","name":"Ashlands Botanical Essence","max_quantity":1000},{"id":"GEM_DUST","kind":"item","resource_id":"GEM_DUST","name":"Gem Dust","max_quantity":1000},{"id":"REGIONAL_CATALYST","kind":"item","resource_id":"REGIONAL_CATALYST","name":"Regional Catalyst","max_quantity":1000},